def most_common_word(words):
    counts = {}
    originals = {}

    for word in words:
        key = word.casefold()
        if key not in counts:
            counts[key] = 0
            originals[key] = word
        counts[key] += 1

    if not counts:
        return None

    return originals[max(counts, key=counts.get)]

def intersection_labels(first, second):
    if not first or not second:
        return None

    second_labels = {label.casefold() for label in second}
    seen = set()
    result = []

    for label in first:
        normalized = label.casefold()
        if normalized in second_labels and normalized not in seen:
            result.append(label)
            seen.add(normalized)

    return tuple(result)

def common_suffix(words):
    words = list(words)
    if not words:
        return None

    suffix = words[0]
    for word in words[1:]:
        length = 0
        while (
            length < len(suffix)
            and length < len(word)
            and suffix[-1 - length] == word[-1 - length]
        ):
            length += 1
        suffix = suffix[len(suffix) - length:]
        if not suffix:
            break

    return suffix

def parse_clock(text):
    import re

    match = re.fullmatch(r"(1[0-2]|[1-9]):([0-5]\d) ([AP]M)", text)
    if match is None:
        raise ValueError("invalid clock value")

    hour = int(match.group(1))
    minute = int(match.group(2))
    period = match.group(3)

    if period == "AM":
        if hour == 12:
            hour = 0
    elif hour != 12:
        hour += 12

    return hour * 60 + minute

def sort_events(events):
    if not events:
        return None
    from datetime import datetime
    return tuple(sorted(events, key=lambda event: datetime.fromisoformat(event["time"])))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    left_columns = len(left[0])
    right_columns = len(right[0])

    if any(len(row) != left_columns for row in left):
        raise ValueError("left must be rectangular")
    if any(len(row) != right_columns for row in right):
        raise ValueError("right must be rectangular")
    if left_columns != len(right):
        raise ValueError("incompatible matrix dimensions")

    return [
        [
            sum(left_row[k] * right[k][j] for k in range(left_columns))
            for j in range(right_columns)
        ]
        for left_row in left
    ]

def count_islands(grid):
    if not grid:
        return None

    columns = len(grid[0])
    if any(len(row) != columns for row in grid):
        raise ValueError("grid must be rectangular")

    if any(cell not in (0, 1) for row in grid for cell in row):
        raise ValueError("grid must contain only 0 and 1")

    if columns == 0:
        return 0

    rows = len(grid)
    visited = [[False] * columns for _ in range(rows)]
    islands = 0

    for row in range(rows):
        for column in range(columns):
            if grid[row][column] != 1 or visited[row][column]:
                continue

            islands += 1
            stack = [(row, column)]
            visited[row][column] = True

            while stack:
                current_row, current_column = stack.pop()
                for next_row, next_column in (
                    (current_row - 1, current_column),
                    (current_row + 1, current_column),
                    (current_row, current_column - 1),
                    (current_row, current_column + 1),
                ):
                    if (
                        0 <= next_row < rows
                        and 0 <= next_column < columns
                        and not visited[next_row][next_column]
                        and grid[next_row][next_column] == 1
                    ):
                        visited[next_row][next_column] = True
                        stack.append((next_row, next_column))

    return islands
